// frontend/src/admin/AdminLogin.jsx
import React, { useState } from 'react';
import axios from './axiosConfig';
import { SiteImage } from '../utils/SiteImage';

// ============================================================
//  Admin Features (روی Brand Panel)
// ============================================================
const ADMIN_FEATURES = [
  { icon: '📊', iconKey: 'icon_chart', title: 'داشبورد کامل', desc: 'آمار زنده فروش و سود' },
  { icon: '📋', iconKey: 'icon_clipboard', title: 'مدیریت سفارشات', desc: 'پیگیری و تغییر وضعیت' },
  { icon: '💳', iconKey: 'icon_payment', title: 'تأیید پرداخت', desc: 'بررسی فیش‌های واریزی' },
  { icon: '👥', iconKey: 'icon_users', title: 'مدیریت کاربران', desc: 'پیام و پشتیبانی مستقیم' },
];

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function AdminLogin() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // ============================================================
  //  Submit
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await axios.post('/admin/auth/login', {
        username: username.trim(),
        password,
      });

      const data = response.data || {};

      if (!data.success) {
        setError(data.detail || 'نام کاربری یا رمز عبور اشتباه است.');
        return;
      }

      if (!data.token) {
        setError('پاسخ سرور ناقص است (توکن دریافت نشد). لطفاً با پشتیبانی تماس بگیرید.');
        return;
      }

      localStorage.setItem('adminToken', data.token);
      localStorage.setItem('adminUser', JSON.stringify(data.user || {}));

      window.location.href = '/admin';
    } catch (err) {
      console.error('خطا در ورود:', err);
      setError(err.response?.data?.detail || 'نام کاربری یا رمز عبور اشتباه است.');
    } finally {
      setLoading(false);
    }
  };

  const canSubmit = Boolean(username.trim() && password && !loading);

  // ============================================================
  //  رندر
  // ============================================================
  return (
    <div
      className="min-h-screen min-h-[100dvh] flex bg-paper-100 dark:bg-ink-900 safe-top safe-bottom"
      dir="rtl"
    >

      {/* ============================================================ */}
      {/*  Brand Panel (دسکتاپ ≥ lg) — Editorial Dark                    */}
      {/* ============================================================ */}
      <div className="hidden lg:flex lg:w-1/2 xl:w-2/5 bg-ink-900 dark:bg-ink-950 text-cream-100 relative overflow-hidden noise-overlay">

        {/* Decorative shapes */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-brand-500/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl" aria-hidden="true" />
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-brand-500/5 rounded-full translate-y-1/2 -translate-x-1/2 blur-3xl" aria-hidden="true" />
        <div className="absolute top-1/3 left-1/4 w-40 h-40 bg-brand-500/5 rounded-full blur-2xl" aria-hidden="true" />

        {/* Overline تزئینی بالا */}
        <div className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500" aria-hidden="true" />

        {/* Floating icons */}
        <div className="absolute top-20 right-20 text-5xl opacity-[0.08] animate-float select-none pointer-events-none" aria-hidden="true">📊</div>
        <div className="absolute bottom-40 left-20 text-6xl opacity-[0.08] animate-float select-none pointer-events-none" style={{ animationDelay: '1s' }} aria-hidden="true">💳</div>
        <div className="absolute top-1/2 left-1/3 text-4xl opacity-[0.08] animate-float select-none pointer-events-none" style={{ animationDelay: '2s' }} aria-hidden="true">🎫</div>

        {/* Content */}
        <div className="relative flex flex-col justify-between p-10 xl:p-12 w-full">

          {/* Logo */}
          <div className="flex items-center gap-3">
            <div className="w-14 h-14 rounded-3xl bg-brand-gradient flex items-center justify-center text-3xl shadow-brand" aria-hidden="true">
              🐾
            </div>
            <div>
              <div className="font-display font-black text-lg">پنل مدیریت</div>
              <div className="text-[11px] text-cream-300/80 mt-0.5">سیستم تغذیه اختصاصی سگ</div>
            </div>
          </div>

          {/* Hero text */}
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/8 backdrop-blur border border-white/15 text-[11px] font-black mb-5">
              <span className="w-2 h-2 rounded-full bg-accent-400 animate-pulse" aria-hidden="true"></span>
              <span>ورود امن مدیران سیستم</span>
            </div>

            <h1 className="font-display font-black text-3xl xl:text-4xl leading-tight tracking-tightest mb-4">
              مدیریت{' '}
              <span className="text-brand-300">هوشمند</span>
              <br />
              سفارشات و کاربران
            </h1>

            <p className="text-sm xl:text-base text-cream-200/80 leading-relaxed max-w-md mb-8">
              تمام ابزارهای لازم برای مدیریت فروش، سفارشات، پرداخت‌ها و پشتیبانی کاربران در یک پنل قدرتمند.
            </p>

            {/* Features Grid */}
            <div className="grid grid-cols-2 gap-3 max-w-md">
              {ADMIN_FEATURES.map((f, i) => (
                <div key={i} className="bg-white/8 backdrop-blur rounded-3xl p-3 border border-white/10">
                  <div className="text-2xl mb-1.5" aria-hidden="true">{f.icon}</div>
                  <div className="text-xs font-display font-black mb-0.5">{f.title}</div>
                  <div className="text-[10px] text-cream-300/80 leading-relaxed font-bold">{f.desc}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Footer */}
          <div className="text-[11px] text-cream-400/60">
            © ۲۰۲۶ سیستم تغذیه اختصاصی سگ — تمام حقوق محفوظ است
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Form Panel — Editorial                                     */}
      {/* ============================================================ */}
      <div className="flex-1 flex items-center justify-center p-3 sm:p-6 lg:p-10 relative overflow-hidden min-h-[100dvh]">

        {/* Decorative shapes (موبایل) */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-brand-300/20 dark:bg-brand-500/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl" aria-hidden="true" />
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-brand-400/15 dark:bg-brand-500/5 rounded-full translate-y-1/2 -translate-x-1/2 blur-3xl" aria-hidden="true" />

        <div className="w-full max-w-md relative">

          {/* ============================================================ */}
          {/*  موبایل: Back + Logo                                          */}
          {/* ============================================================ */}
          <div className="lg:hidden flex items-center justify-between mb-4">
            <a
              href="/"
              className="inline-flex items-center gap-1.5 text-sm text-ink-500 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 font-black transition min-h-[44px] px-2 py-2 rounded-2xl hover:bg-brand-50 dark:hover:bg-ink-800 touch-target"
            >
              <SiteImage imageKey="icon_arrow_back" fallback="→" alt="" className="leading-none inline-flex" />
              <span>خانه</span>
            </a>
            <div className="flex items-center gap-2">
              <div className="w-9 h-9 rounded-2xl bg-brand-gradient flex items-center justify-center text-xl shadow-brand" aria-hidden="true">
                🐾
              </div>
              <span className="font-display font-black text-sm text-ink-800 dark:text-cream-100">پنل مدیریت</span>
            </div>
          </div>

          {/* ============================================================ */}
          {/*  Card — Editorial                                             */}
          {/* ============================================================ */}
          <div className="relative bg-paper-50 dark:bg-ink-800 rounded-3xl shadow-editorial border border-ink-200 dark:border-dark-700 overflow-hidden">

            {/* Overline تزئینی بالای card */}
            <div className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500 z-10" aria-hidden="true" />

            {/* Header */}
            <div className="p-5 sm:p-7 border-b border-ink-200 dark:border-dark-700 bg-brand-50/50 dark:bg-brand-500/10">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 rounded-3xl bg-brand-gradient flex items-center justify-center text-white text-2xl flex-shrink-0 shadow-brand" aria-hidden="true">
                  🔐
                </div>
                <div className="min-w-0">
                  <h1 className="font-display font-black text-base sm:text-xl text-ink-800 dark:text-cream-100">
                    ورود مدیر
                  </h1>
                  <p className="text-xs text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                    برای دسترسی به پنل، وارد شوید
                  </p>
                </div>
              </div>
            </div>

            {/* Body */}
            <div className="p-5 sm:p-7">

              {/* Error — Editorial rose */}
              {error && (
                <div className="mb-5 bg-rose-50 dark:bg-rose-500/15 border-2 border-rose-200 dark:border-rose-500/30 rounded-2xl p-3 sm:p-3.5 flex items-start gap-3 animate-slide-down">
                  <div className="w-9 h-9 rounded-full bg-rose-500 flex items-center justify-center text-white text-lg flex-shrink-0 shadow-soft" aria-hidden="true">
                    ⚠️
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-display font-black text-rose-900 dark:text-rose-200 text-xs mb-0.5">
                      خطا در ورود
                    </div>
                    <div className="text-[11px] text-rose-700 dark:text-rose-300 leading-relaxed break-safe font-bold">
                      {error}
                    </div>
                  </div>
                </div>
              )}

              {/* Form */}
              <form onSubmit={handleSubmit} className="space-y-4">

                {/* Username */}
                <div>
                  <label className="block text-xs font-black text-ink-700 dark:text-cream-300 mb-1.5">
                    نام کاربری
                  </label>
                  <div className="relative">
                    <SiteImage imageKey="icon_user" fallback="👤" alt="" className="absolute right-3.5 top-1/2 -translate-y-1/2 text-ink-400 dark:text-cream-500 text-base pointer-events-none" />
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      placeholder="admin"
                      autoComplete="username"
                      disabled={loading}
                      autoFocus
                      className="w-full px-4 py-3.5 pr-11 min-h-[52px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-mono tabular-nums"
                      dir="ltr"
                    />
                  </div>
                </div>

                {/* Password */}
                <div>
                  <label className="block text-xs font-black text-ink-700 dark:text-cream-300 mb-1.5">
                    رمز عبور
                  </label>
                  <div className="relative">
                    <SiteImage imageKey="icon_lock" fallback="🔒" alt="" className="absolute right-3.5 top-1/2 -translate-y-1/2 text-ink-400 dark:text-cream-500 text-base pointer-events-none" />
                    <input
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="••••••••"
                      autoComplete="current-password"
                      disabled={loading}
                      className="w-full px-4 py-3.5 pr-11 pl-12 min-h-[52px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-mono"
                      dir="ltr"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute left-2 top-1/2 -translate-y-1/2 w-9 h-9 flex items-center justify-center text-ink-400 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 rounded-2xl transition text-base touch-target"
                      title={showPassword ? 'پنهان کردن' : 'نمایش'}
                      aria-label={showPassword ? 'پنهان کردن رمز' : 'نمایش رمز'}
                      tabIndex={-1}
                    >
                      {showPassword ? '🙈' : '👁️'}
                    </button>
                  </div>
                </div>

                {/* Submit — Editorial brand */}
                <button
                  type="submit"
                  disabled={!canSubmit}
                  className={`w-full py-3.5 min-h-[52px] rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-brand touch-target ${
                    !canSubmit
                      ? 'bg-paper-200 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed shadow-none'
                      : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white hover:shadow-brand-lg hover:-translate-y-0.5 active:translate-y-0'
                  }`}
                >
                  {loading ? (
                    <>
                      <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      <span>در حال ورود...</span>
                    </>
                  ) : (
                    <>
                      <SiteImage imageKey="icon_lock" fallback="🔐" alt="" className="text-lg" />
                      <span>ورود به پنل مدیریت</span>
                    </>
                  )}
                </button>
              </form>

            </div>

            {/* Footer */}
            <div className="px-5 sm:px-6 py-4 bg-paper-100 dark:bg-ink-900/30 border-t border-ink-200 dark:border-dark-700 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <a
                href="/"
                className="text-[11px] text-ink-500 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 font-black transition flex items-center gap-1 min-h-[36px] touch-target"
              >
                <SiteImage imageKey="icon_house" fallback="🏠" alt="" className="leading-none inline-flex" />
                <span>بازگشت به صفحه اصلی</span>
              </a>
              <div className="text-[10px] text-ink-400 dark:text-cream-500 flex items-center gap-1 font-bold">
                <span className="w-1.5 h-1.5 rounded-full bg-accent-400 animate-pulse" aria-hidden="true"></span>
                <span>اتصال امن SSL</span>
              </div>
            </div>
          </div>

          {/* Footer note (موبایل) */}
          <div className="lg:hidden text-center mt-5 text-[11px] text-ink-400 dark:text-cream-500 font-bold">
            © ۲۰۲۶ سیستم تغذیه اختصاصی سگ
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Global animations                                           */}
      {/* ============================================================ */}
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(5deg); }
        }
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
      `}</style>

    </div>
  );
}