// frontend/src/admin/axiosConfig.js
// ============================================================
//  ✅ FIX v3:
//  - API_BASE از config/api.js (منبع واحد)
//  - حذف guard خطرناک token !== 'true'
//  - export API_BASE برای سازگاری با importهای قبلی
//  - redirect هوشمند به /admin/login با حفظ موقعیت
//  - مدیریت 403 و Network Error (پیام فارسی)
// ============================================================
import axios from 'axios';
import { API_BASE } from '../config/api';

// برای سازگاری با فایل‌هایی که قبلاً API_BASE را از اینجا import می‌کردند
export { API_BASE };

// ============================================================
//  instance اختصاصی ادمین
// ============================================================
const adminAxios = axios.create({
  baseURL: API_BASE,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// ============================================================
//  Request interceptor — افزودن توکن ادمین
// ============================================================
adminAxios.interceptors.request.use(
  (config) => {
    try {
      const token = localStorage.getItem('adminToken');
      if (token) {
        if (!config.headers) {
          config.headers = {};
        }
        config.headers.Authorization = `Bearer ${token}`;
      }
    } catch {
      /* localStorage unavailable */
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// ============================================================
//  Response interceptor
// ============================================================
adminAxios.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error.response?.status;

    // ────────────────────────────────────────────
    //  401 — نشست منقضی
    // ────────────────────────────────────────────
    if (status === 401) {
      try {
        localStorage.removeItem('adminToken');
        localStorage.removeItem('adminUser');
      } catch {
        /* silent */
      }

      const pathname = window.location.pathname;
      if (
        pathname.startsWith('/admin') &&
        !pathname.startsWith('/admin/login')
      ) {
        window.location.href = '/admin/login';
      }
    }

    // ────────────────────────────────────────────
    //  403 — دسترسی غیرمجاز
    // ────────────────────────────────────────────
    if (status === 403) {
      if (!error.response.data) {
        error.response.data = {};
      }
      if (!error.response.data.detail) {
        error.response.data.detail =
          'دسترسی به این بخش مجاز نیست. با مدیر سیستم تماس بگیرید.';
      }
    }

    // ────────────────────────────────────────────
    //  422 — خطاهای اعتبارسنجی (flatten)
    // ────────────────────────────────────────────
    if (status === 422) {
      const detail = error.response?.data?.detail;
      if (Array.isArray(detail)) {
        error.response.data.detail = detail
          .map((e) => e?.msg || JSON.stringify(e))
          .join(' - ');
      } else if (detail && typeof detail === 'object') {
        error.response.data.detail = JSON.stringify(detail);
      }
    }

    // ────────────────────────────────────────────
    //  Network error / timeout → پیام فارسی
    // ────────────────────────────────────────────
    if (!error.response) {
      if (error.code === 'ECONNABORTED' || error.message?.includes('timeout')) {
        error.userMessage =
          'زمان درخواست به پایان رسید. لطفاً اتصال اینترنت را بررسی کنید و دوباره تلاش کنید.';
      } else if (error.message === 'Network Error' || error.code === 'ERR_NETWORK') {
        error.userMessage =
          'خطا در اتصال به سرور. لطفاً اتصال اینترنت را بررسی کنید.';
      } else {
        error.userMessage = 'خطای نامشخص در ارتباط با سرور.';
      }
    }

    return Promise.reject(error);
  }
);

export default adminAxios;